<?php
declare(strict_types=1);
if (isset($_GET['art'])) {
    header('Content-Type: image/webp');
    header('Cache-Control: public, max-age=86400');
    echo base64_decode(''); exit;
}

if (isset($_GET['source'])) {
    $index = file_get_contents(__DIR__ . '/index.php');
    if ($index !== false && preg_match('~href="([^"]+/2007/12/php-regular-expressions-recursion-named\.html)"~', $index, $m)) {
        header('Location: ' . html_entity_decode($m[1], ENT_QUOTES), true, 302); exit;
    }
    http_response_code(404); exit('Source link unavailable.');
}
if ($_SERVER['REQUEST_METHOD'] === 'POST') {
    header('Content-Type: application/json');
    $data = json_decode(file_get_contents('php://input'), true);
    $text = is_array($data) && is_string($data['text'] ?? null) ? $data['text'] : '';
    if (strlen($text) > 2000) { http_response_code(413); echo json_encode(['error'=>'Keep the expedition under 2,000 bytes.']); exit; }
    $match = preg_match('~\A((?:[^()]++|\((?1)\))*)\z~u', $text);
    echo json_encode(['balanced'=>$match === 1, 'engine'=>'PHP / PCRE recursive group (?1)', 'error'=>$match === false ? preg_last_error_msg() : null]); exit;
}
