main{max-width:1180px;margin:auto;padding:28px 26px 60px}.mast{display:flex;justify-content:space-between;gap:20px;font:12px/1.4 "Courier New",monospace;letter-spacing:2px;text-transform:uppercase;border-bottom:2px solid var(--ink);padding-bottom:18px}
header{display:grid;grid-template-columns:1.35fr 1fr;gap:50px;align-items:end;padding:42px 0 28px}.kicker{font:12px "Courier New",monospace;color:var(--orange);letter-spacing:2px;text-transform:uppercase}h1{font-size:clamp(44px,6vw,82px);font-weight:normal;line-height:.96;letter-spacing:-3px;margin:16px 0 22px}h1 em{color:var(--orange)}header p{margin:0 0 10px;max-width:420px}h2{font-size:30px;font-weight:normal;margin:0 0 12px}p{margin-top:0}
