.deck{display:grid;grid-template-columns:minmax(0,1.6fr) minmax(0,1fr);gap:32px;margin-top:42px}.console{border-top:2px solid var(--ink);padding-top:20px}.sectionline{display:flex;justify-content:space-between;align-items:center;gap:12px}.tag{font:12px "Courier New",monospace;color:var(--muted)}label{display:block;margin:16px 0 8px}textarea{width:100%;resize:vertical;min-height:104px;background:#fffaf0;color:var(--ink);border:1px solid #99a2a1;padding:15px;font:19px/1.6 "Courier New",monospace;border-radius:3px}.controls{display:flex;flex-wrap:wrap;gap:8px;margin:12px 0 20px}.controls button{font-size:15px}.tokens{padding:15px;background:#e8e0cb;display:flex;flex-wrap:wrap;align-items:center;gap:3px;min-height:68px;font:18px "Courier New",monospace;white-space:pre-wrap;overflow-wrap:anywhere}.tokens button{font:23px "Courier New",monospace;padding:4px 7px;min-height:44px;background:#fff8e7;border-color:#b3ad9b}.tokens button.selected{background:var(--ink);color:var(--gold)}.tokens button.bad{background:#ffd8c5;border-color:var(--orange)}.feedback{min-height:65px;margin:12px 0 0;color:var(--muted);font-size:16px}.status{border-left:4px solid var(--orange);padding:8px 12px;font:14px/1.5 "Courier New",monospace;margin:15px 0}.status.good{border-color:#287267}
