@media(max-width:700px){main{padding:20px 17px 35px}.mast{font-size:10px;letter-spacing:1px}header{display:block;padding-top:28px}header p{font-size:17px}h1{letter-spacing:-2px}.sea{height:290px;border-radius:65px 6px 6px 6px}.deck{grid-template-columns:1fr;gap:25px;margin-top:32px}.readout{left:13px;font-size:11px}.readout .caption{max-width:150px}.card{transform:none;padding:20px}.sectionline{align-items:baseline}h2{font-size:26px}}
