<body><main>
<nav class="mast"><a href="./">Chloe Reads Jon</a><span>Expedition 07 / October 2026</span></nav>
<header><div><span class="kicker">A pocket voyage into recursion</span><h1>The Parenthesis<br><em>Submarine.</em></h1></div><p>Every <b>(</b> is a dive. Every <b>)</b> brings you up.<br>Repair six little sea messages, or type your own and watch its hidden depths unfold. No timer. No maths exam. Just a submarine with impeccable punctuation.</p></header>
<div class="sea"><img id="oceanArt" src="?art=1" alt="An original painted submarine expedition through glowing coral arches beneath a midnight-blue sea."><svg id="route" viewBox="0 0 1000 300" role="img" aria-label="A depth trace of the current parentheses"></svg><div class="readout"><div><span>DEEPEST DIVE</span><strong id="depth">0</strong></div><span class="caption" id="seaCaption">Surface conditions: suspiciously grammatical.</span></div></div>
<div class="deck">
<section class="console"><div class="sectionline"><h2>01 / The dive console</h2><span class="tag" id="position">Ready to explore</span></div>
<label for="signal">Your sea message <span class="note">(up to 500 characters)</span></label>
<textarea id="signal" maxlength="500" spellcheck="false">(reef (cave (pearl)) fish)</textarea>
<div class="controls"><button id="trace" class="primary">Play the dive</button><button id="sample">Load a deeper example</button><button id="clear">Clear</button></div>
<div class="tokens" id="tokens" aria-label="Select a bracket to find its partner"></div>
<p class="feedback" id="feedback" aria-live="polite">Tap a bracket to find its partner and inspect its depth.</p>
<div class="status" id="status" aria-live="polite">Checking the hull…</div><p class="note">The route treats all other characters as cargo. This is a parentheses explorer, not a full programming-language parser: brackets inside quoted strings count too.</p></section>
<aside class="card"><span class="mission" id="mission">SALVAGE MESSAGE 1 / 6</span><h2 id="missionTitle">The missing surface</h2><p id="brief"></p><button id="load" class="primary">Load this message</button><div class="controls"><button id="check">Check my repair</button><button id="hint">A little hint</button></div><p id="result" class="result" aria-live="polite"></p><button id="next" hidden>Next salvage message →</button><p class="note">Change only parentheses. Keep the cargo words, and use the fewest edits requested. Each repair has more than one possible solution.</p></aside>
</div>
<details class="details"><summary>Why does a regex need to recurse?</summary><p>A flat pair is easy. A pair containing another pair containing another pair needs the same rule again, inside itself. Jon’s post spotted PHP’s <b>(?1)</b>: “run capture group 1 again”. Here is the fixed expression actually used by this page:</p><code>~\A((?:[^()]++|\((?1)\))*)\z~u</code><p><b>[^()]++</b> carries ordinary text. <b>\( … \)</b> wraps a matched pair. <b>(?1)</b> handles whatever is inside that pair. The anchors require the entire message to fit. The browser draws the route using a stack; the PHP server separately checks the recursive regex. Different machinery, same little ocean.</p></details>
<footer><span>Inspired by Jon’s <a href="?source=1">PHP Regular Expressions: Recursion, Named Capture</a>.</span><span>Made for curious captains, large and small.</span></footer>
</main>
<script>
'use strict';
const $=id=>document.getElementById(id);
const missions=[
{title:'The missing surface',text:'(reef (pearl)',edits:1,hint:'Two dives, one return. Add one closing bracket.',brief:'A pearl diver forgot to return to the surface. Repair the message by adding just one bracket.'},
{title:'One return too many',text:'(crab) shell)',edits:1,hint:'There is a return with no dive. Remove one closing bracket.',brief:'This crab has surfaced twice after diving once. Remove just one bracket.'},
{title:'Backwards at the harbour',text:')boat(',edits:2,hint:'Replace the first bracket with an opening one and the last with a closing one. Removing both also works.',brief:'Two harbour gates face the wrong way. Make the message balanced in two bracket edits.'},
{title:'The sunken lantern',text:'(kelp (cave (lantern))',edits:1,hint:'Three openings, two closings. One more return is needed.',brief:'The lantern is safe, but one outer voyage never ended. Add just one bracket.'},
{title:'False alarm at depth',text:'(eel)) (ray (shell))',edits:1,hint:'The eel returns once too often. Remove one closing bracket before the ray.',brief:'An extra surface signal interrupts two otherwise lovely dives. Remove just one bracket.'},
{title:'The final salvage',text:'((anchor) (chest (gold)',edits:2,hint:'Four openings and two closings: you need two more returns.',brief:'The anchor and treasure chest are both still underwater. Add just two brackets to bring the whole expedition home.'}
];
let mission=0, pairs=new Map(), depths=[], tracePoints=[], timer=null, revision=0, completed=false, loaded=false;
function stop(){clearInterval(timer);timer=null;$('trace').textContent='Play the dive';}
function inspect(){
stop();revision++;const text=$('signal').value;let stack=[],bad=[],max=0;depths=[];pairs=new Map();tracePoints=[{i:0,d:0}];
[...text].forEach((c,i)=>{if(c==='('){stack.push(i);max=Math.max(max,stack.length);depths[i]=stack.length;}else if(c===')'){depths[i]=stack.length;if(stack.length){const j=stack.pop();pairs.set(i,j);pairs.set(j,i);}else bad.push(i);}tracePoints.push({i:i+1,d:stack.length});});
bad.push(...stack);$('depth').textContent=max;$('seaCaption').textContent=bad.length?'A bracket is lost at sea.':'All dives return safely to the surface.';$('position').textContent=pairs.size/2+' matched pairs';
$('tokens').replaceChildren();[...text].forEach((c,i)=>{if(c==='('||c===')'){const b=document.createElement('button');b.textContent=c;b.dataset.index=i;b.classList.toggle('bad',bad.includes(i));b.setAttribute('aria-label',(c==='('? 'Opening':'Closing')+' bracket at character '+(i+1));b.onclick=()=>select(i);$('tokens').append(b);}else{const t=document.createElement('span');t.textContent=c;$('tokens').append(t);}});
$('feedback').textContent=text?'Tap a bracket to find its partner and inspect its depth.':'The empty ocean is balanced. Type something to begin.';
draw();verify(text,revision);
}
function select(i){document.querySelectorAll('#tokens button').forEach(b=>b.classList.toggle('selected',Number(b.dataset.index)===i||Number(b.dataset.index)===pairs.get(i)));
$('feedback').textContent=pairs.has(i)?'Character '+(i+1)+' pairs with character '+(pairs.get(i)+1)+' at depth '+depths[i]+'. The same rule holds at every depth.':'Character '+(i+1)+' has no partner. A small repair will get it home.';
draw(i+1);}
function draw(cursor=null){
const n=[...$('signal').value].length,max=Math.max(1,...tracePoints.map(p=>p.d));const x=i=>45+(i/Math.max(n,1))*910,y=d=>42+(d/max)*170;
const pts=tracePoints.map(p=>x(p.i)+','+y(p.d)).join(' ');let html='';
for(let d=0;d<=max;d++){if(d>0&&max>8&&d!==max)continue;html+='<line x1="30" x2="970" y1="'+y(d)+'" y2="'+y(d)+'" stroke="#f9efcb" opacity=".18"/>';}
html+='<polyline points="'+pts+'" fill="none" stroke="#ffd46c" stroke-width="4" stroke-linejoin="round"/>';
const p=cursor===null?tracePoints[tracePoints.length-1]:tracePoints[Math.min(cursor,tracePoints.length-1)];
html+='<g transform="translate('+x(p.i)+','+y(p.d)+')"><ellipse rx="18" ry="10" fill="#ff8b50" stroke="#fff3bf" stroke-width="2"/><circle cx="5" cy="0" r="4" fill="#102e3b"/><path d="M-18 -5 L-26 -10 L-26 10 L-18 5" fill="#ffd46c"/></g>';
$('route').innerHTML=html;
}
async function verify(text,version){$('status').textContent='Checking the real PHP recursive regex…';$('status').classList.remove('good');try{const r=await fetch('parenthesis-submarine.php',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({text})});const data=await r.json();if(version!==revision)return;if(!r.ok||data.error)throw Error(data.error||'Server check failed');$('status').textContent=data.balanced?'PCRE verdict: balanced. Every nested pair matches.':'PCRE verdict: not balanced. Repair a dive or a return.';$('status').classList.toggle('good',data.balanced);}catch(e){if(version===revision)$('status').textContent='The live PHP check is unavailable. The local depth explorer still works.';}}
function showMission(){const m=missions[mission];$('mission').textContent='SALVAGE MESSAGE '+(mission+1)+' / 6';$('missionTitle').textContent=m.title;$('brief').textContent=m.brief;$('result').textContent='';$('next').hidden=true;$('load').disabled=false;$('check').disabled=false;completed=false;loaded=false;}
function distance(a,b){let row=Array.from({length:b.length+1},(_,i)=>i);for(let i=0;i<a.length;i++){let next=[i+1];for(let j=0;j<b.length;j++)next[j+1]=Math.min(row[j+1]+1,next[j]+1,row[j]+(a[i]===b[j]?0:1));row=next;}return row[b.length];}
$('signal').addEventListener('input',inspect);
$('load').onclick=()=>{$('signal').value=missions[mission].text;loaded=true;inspect();$('result').textContent='Message loaded. Repair it in the dive console, then check.';$('signal').focus();};
$('check').onclick=()=>{if(!loaded){$('result').textContent='Load this salvage message first so you can repair its brackets.';return;}const m=missions[mission],s=$('signal').value;const cargo=t=>t.replace(/[()]/g,'');if(cargo(s)!==cargo(m.text)){$('result').textContent='Keep the cargo words and spaces unchanged. Only edit parentheses.';return;}if([...s].filter(c=>c==='('||c===')').length!==pairs.size){$('result').textContent='Not home yet. Tap a lonely bracket to investigate.';return;}if(distance(m.text,s)!==m.edits){$('result').textContent='Balanced! Now try the same rescue in exactly '+m.edits+' bracket edit'+(m.edits===1?'':'s')+'.';return;}
completed=true;$('result').textContent=mission===5?'All six messages salvaged. Captain, your punctuation is seaworthy. Try inventing a deeper voyage!':'Safely surfaced! The cargo is intact and every dive has a return.';$('next').textContent=mission===5?'Sail again →':'Next salvage message →';$('next').hidden=false;$('check').disabled=true;};
$('hint').onclick=()=>{$('result').textContent=missions[mission].hint;};
$('next').onclick=()=>{if(!completed)return;mission=(mission+1)%missions.length;showMission();};
$('trace').onclick=()=>{if(timer){stop();return;}let i=0;$('trace').textContent='Pause the dive';draw(0);timer=setInterval(()=>{i++;draw(i);if(i>=tracePoints.length-1)stop();},Math.max(45,1800/tracePoints.length));};
$('sample').onclick=()=>{$('signal').value='(ocean (reef (cave (chest (pearl)))) (kelp (crab)))';inspect();};
$('clear').onclick=()=>{$('signal').value='';inspect();$('signal').focus();};
showMission();inspect();
</script></body></html>